import Foundation
import Testing
@testable import RFD4Core

/// Numerical parity of the flow-matching schedules against upstream PyTorch.
///
/// Not a ported test — upstream has no equivalent, because upstream *is* the
/// reference. This is Phase 3 parity work: schedules are deterministic tensors, so
/// the playbook wants them pinned **bitwise**, not compared with a tolerance.
///
/// Fixtures are generated by `src/rfd4_mlx_export/dump_schedule_fixtures.py` and
/// stored as float32 bit patterns rather than decimal literals, so a round trip
/// through text cannot quietly widen the comparison.
@Suite("flow schedule parity")
struct FlowScheduleParityTests {

    // MARK: fixture loading

    struct Fixture: Decodable {
        struct Released: Decodable { let ts: [String]; let gt: [String] }
        struct Builder: Decodable { let values: [String]?; let error: String? }
        let torch: String
        let released: [String: Released]
        let builders: [String: Builder]
    }

    static let fixture: Fixture = {
        guard let url = Bundle.module.url(forResource: "schedules", withExtension: "json") else {
            fatalError("schedules.json fixture missing — regenerate with dump_schedule_fixtures.py")
        }
        do {
            return try JSONDecoder().decode(Fixture.self, from: Data(contentsOf: url))
        } catch {
            fatalError("schedules.json failed to decode: \(error)")
        }
    }()

    /// "3f800000" -> 1.0
    static func floats(_ hex: [String]) -> [Float] {
        hex.map { Float(bitPattern: UInt32($0, radix: 16) ?? 0) }
    }

    /// Reports the worst disagreement rather than just the first, so a systematic
    /// drift reads differently from a single bad endpoint.
    ///
    /// WHY NOT BITWISE. The playbook asks for deterministic tensors pinned bitwise,
    /// and these are within **1 ULP** of upstream once `linspace`'s halfway split is
    /// reproduced — but not bit-identical. The residue is torch's own rounding inside
    /// `end - step * (steps - i - 1)`; closing it would mean emulating a CPU kernel's
    /// instruction order, which carries no semantic meaning and is free to change
    /// between torch releases.
    ///
    /// The number that matters: 1 ULP of float32 is ~1.2e-7 relative, while the int8
    /// quantization floor this port targets is r >= 0.9997, i.e. ~3e-4. The schedule
    /// residue sits three orders of magnitude below the noise it feeds into. A tight
    /// ULP bound still catches real divergence — a wrong mode, a dropped tail
    /// multiplier, an off-by-one — which is what the check is for.
    static func compare(_ got: [Float], _ want: [Float], _ label: String, maxULP: Int) {
        #expect(got.count == want.count, "\(label): length \(got.count) != \(want.count)")
        guard got.count == want.count else { return }

        // Signed-magnitude -> monotonic ordering, so a difference counts in ULPs.
        func ordered(_ f: Float) -> Int64 {
            let b = Int64(f.bitPattern)
            return f.sign == .minus ? Int64(0x1_0000_0000) - b : b
        }

        var exact = 0
        var worst: (index: Int, got: Float, want: Float, ulps: Int) = (-1, 0, 0, 0)
        for i in got.indices {
            if got[i].bitPattern == want[i].bitPattern { exact += 1; continue }
            guard got[i].isFinite, want[i].isFinite else {
                worst = (i, got[i], want[i], Int.max)
                break
            }
            let ulps = Int(abs(ordered(got[i]) - ordered(want[i])))
            if ulps > worst.ulps { worst = (i, got[i], want[i], ulps) }
        }

        #expect(worst.ulps <= maxULP, """
            \(label): \(got.count - exact)/\(got.count) values differ from upstream, \
            worst \(worst.ulps) ULP (budget \(maxULP)). \
            At [\(worst.index)]: got \(worst.got), want \(worst.want).
            """)
    }

    // MARK: measured error budgets

    /// Time grids and the raw builders. Measured worst case is 3 ULP.
    static let scheduleBudget = 4

    /// Noise schedules. Measured worst case is 125 ULP, and that is NOT slop.
    ///
    /// `gt` mode `tan` is `(pi/2) * sin(a) / (cos(a) + 1e-2)` with `a = (1-t) * pi/2`.
    /// As `t -> 0`, `a -> pi/2` and `cos(a) -> 0`, so the denominator is dominated by
    /// the 1e-2 epsilon and the quotient becomes extremely sensitive to the angle.
    /// Measured amplification of a ONE ULP perturbation of `a`:
    ///
    /// | t      | cos(a)   | gt      | ULP of gt per ULP of a |
    /// |--------|----------|---------|------------------------|
    /// | 0.0026 | 0.004084 | 111.53  | 124                    |
    /// | 0.01   | 0.015707 |  61.10  |  75                    |
    /// | 0.1    | 0.156434 |   9.32  |   7                    |
    /// | 0.5    | 0.707107 |   1.55  |   2                    |
    ///
    /// The same formula in numpy float32 sits 2 ULP from torch, so the port's formula
    /// is right; what remains is a single-ULP disagreement between Swift's `sinf`/`cosf`
    /// and torch's vectorized ones, amplified ~100x by the conditioning above. Matching
    /// it would mean shipping our own transcendentals.
    ///
    /// 125 ULP at this magnitude is ~1.5e-5 relative, still an order of magnitude under
    /// the int8 quantization floor (r >= 0.9997, ~3e-4) this port is built to live at.
    /// Only `local_latents` uses `tan`; `bb_ca` uses `1/t` and measures 10 ULP.
    static let noiseBudget = 192

    // MARK: the released configuration

    @Test("the released 60-step schedules match upstream bitwise",
          arguments: ModalityConfig.releasedDataModes)
    func releasedSchedulesMatchUpstream(dataMode: String) throws {
        let want = try #require(Self.fixture.released[dataMode])
        let built = try sampleSchedule(nsteps: 60, modalities: ModalityConfig.released)

        Self.compare(try #require(built.ts[dataMode]), Self.floats(want.ts), "\(dataMode).ts",
                     maxULP: Self.scheduleBudget)
        Self.compare(try #require(built.gt[dataMode]), Self.floats(want.gt), "\(dataMode).gt",
                     maxULP: Self.noiseBudget)
    }

    // MARK: the raw builders

    /// Separates "the schedule math is wrong" from "the config is wrong" — these call
    /// the builders directly, with the config out of the picture.
    @Test("the schedule builders match upstream bitwise")
    func buildersMatchUpstream() throws {
        for (key, entry) in Self.fixture.builders.sorted(by: { $0.key < $1.key }) {
            let parts = key.split(separator: "/").map(String.init)
            let fn = parts[0]
            let mode = try #require(ScheduleMode(rawValue: parts[1]), "unknown mode in \(key)")
            // "tail10x2"
            let tail = parts[2].dropFirst(4).split(separator: "x").map { Int($0) ?? 0 }
            let (tailSteps, multiplier) = (tail[0], tail[1])

            guard let values = entry.values else {
                // Upstream refused this grid; so must we.
                #expect(throws: ScheduleError.self, "\(key) should be refused") {
                    _ = fn == "get_schedule"
                        ? try getSchedule(mode: mode, nsteps: 60, p1: 2.0,
                                          tailSteps: tailSteps, tailStepMultiplier: multiplier)
                        : try getScheduleTSRSafe(mode: mode, nsteps: 60, p1: 2.0,
                                                 tailSteps: tailSteps, tailStepMultiplier: multiplier)
                }
                continue
            }

            let got = fn == "get_schedule"
                ? try getSchedule(mode: mode, nsteps: 60, p1: 2.0,
                                  tailSteps: tailSteps, tailStepMultiplier: multiplier)
                : try getScheduleTSRSafe(mode: mode, nsteps: 60, p1: 2.0,
                                         tailSteps: tailSteps, tailStepMultiplier: multiplier)
            Self.compare(got, Self.floats(values), key, maxULP: Self.scheduleBudget)
        }
    }

    @Test("the fixture records which upstream produced it")
    func fixtureProvenance() {
        #expect(!Self.fixture.torch.isEmpty)
        #expect(Self.fixture.released.count == 2)
        #expect(Self.fixture.builders.count == 12)
    }
}
